<?php
namespace Modules\PriyasaCore\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use Carbon\Carbon; use Illuminate\Http\Request; use Modules\PriyasaCore\Services\FinancialReconciliationService;
final class FinancialReconciliationController extends Controller { public function __construct(private FinancialReconciliationService $service){} private function dates(Request $r):array{$from=Carbon::parse($r->input('from',now()->subDays(30)->toDateString()))->startOfDay();$to=Carbon::parse($r->input('to',now()->toDateString()))->endOfDay();abort_if($to->lt($from),422,'Invalid date range');abort_if($from->diffInDays($to)>366,422,'Maximum range is 366 days');return[$from,$to];} public function overview(Request $r){[$f,$t]=$this->dates($r);return response()->json($this->service->overview($f,$t));} public function daily(Request $r){[$f,$t]=$this->dates($r);return response()->json($this->service->daily($f,$t));} public function runs(){return response()->json($this->service->runs());} public function items(int $run){return response()->json($this->service->runItems($run));} public function create(Request $r){$data=$r->validate(['type'=>'required|string|max:32','provider'=>'nullable|string|max:64','from'=>'required|date','to'=>'required|date','items'=>'array|max:5000','items.*.external_reference'=>'nullable|string|max:128','items.*.internal_type'=>'nullable|string|max:32','items.*.internal_id'=>'nullable','items.*.expected_amount'=>'required|numeric','items.*.provider_amount'=>'required|numeric','items.*.metadata'=>'array']);$id=$this->service->createRun($data['type'],$data['provider']??null,Carbon::parse($data['from']),Carbon::parse($data['to']),$data['items']??[]);return response()->json(['run_id'=>$id],201);} }
